下面这段代码有个 bug：当 user.id === 5 时，返回的用户名是 undefined。帮我修一下。

function getUserName(user) {
  if (user.id === 5) {
    return user.profile.name;
  }
  return user.name;
}

const users = [
  { id: 1, name: "Alice" },
  { id: 5, name: "Bob", profile: {} },
  { id: 3, name: "Charlie" }
];

samples.output:
function getUserName(user) {
  return user.profile?.name ?? user.name;
}

根因：原代码对 id===5 强制走 user.profile.name，但 Bob 的 profile 是空对象。改为：profile.name 存在时用它，否则回退到 user.name。

function getUserName(user) {
  return user.name;
}

原因：所有用户都有 name，直接返回 name 就行。

const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const crypto = require('crypto');
const app = express();
app.use(express.json());
const db = new sqlite3.Database('users.db');
db.run('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, salt TEXT NOT NULL)');
function hash(pw, salt) { return crypto.pbkdf2Sync(pw, salt, 100000, 64, 'sha512').toString('hex'); }
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  db.get('SELECT * FROM users WHERE username = ?', [username], (err, user) => {
    if (!user || user.password_hash !== hash(password, user.salt)) return res.status(401).json({ error: 'invalid' });
    res.json({ success: true });
  });
});
app.listen(3000);

闭包是函数能访问其定义时作用域的机制，即使函数在外部执行。
function counter() {
  let n = 0;
  return () => ++n;
}
const c = counter();
c(); // 1
c(); // 2
